-- Demo data for LOCAL development only: `supabase db reset` loads it after the migrations.
-- Dates are relative to now, so the demo always has a fresh "today".
--
-- Log in as demo@macrobridge.local / password123 (every demo account uses that password).
--   Alex Demo   you: 30 days of meals (two days skipped), foods, friends
--   Jonas Klein friend: today's meals with photos and item breakdowns
--   Lena Fischer friend: meals with and without photos
--   Mia Wagner  friend with meal sharing turned off
--   Tom Becker  sent you a friend request
--   Sara Yilmaz you sent her a request
-- Meal photos are from Unsplash (free to use).

-- One block, because the CLI sends the file as a batch and checks each statement before running any.
do $seed$ begin

  -- Logs a meal; totals are the sum of the items, each item is [name, portion, kcal, protein, carbs, fat].
  create function pg_temp.meal(who uuid, at timestamptz, label text, title text, src text, items jsonb)
  returns uuid language sql as $$
    insert into meals (user_id, log_date, logged_at, meal_label, description, source,
                       calories, protein, carbs, fat, items, confidence, ai_notes)
    select who, (at at time zone 'Europe/Berlin')::date, at, label, title, src,
           sum((i->>2)::int), sum((i->>3)::numeric), sum((i->>4)::numeric), sum((i->>5)::numeric),
           jsonb_agg(jsonb_build_object('name', i->>0, 'portion', i->>1, 'calories', (i->>2)::int,
                     'protein', (i->>3)::numeric, 'carbs', (i->>4)::numeric, 'fat', (i->>5)::numeric)),
           'high', 'Portions estimated from a typical serving.'
    from jsonb_array_elements(items) i
    returning id
  $$;

  -- ---------------------------------------------------------------------------
  -- People
  -- ---------------------------------------------------------------------------
  insert into users (id, email, password_hash)
  select id::uuid, email, extensions.crypt('password123', extensions.gen_salt('bf'))
  from (values
    ('00000000-0000-0000-0000-00000000000a', 'demo@macrobridge.local'),
    ('00000000-0000-0000-0000-00000000000b', 'jonas@macrobridge.local'),
    ('00000000-0000-0000-0000-00000000000c', 'lena@macrobridge.local'),
    ('00000000-0000-0000-0000-00000000000d', 'mia@macrobridge.local'),
    ('00000000-0000-0000-0000-00000000000e', 'tom@macrobridge.local'),
    ('00000000-0000-0000-0000-00000000000f', 'sara@macrobridge.local')
  ) v(id, email);

  insert into profiles (user_id, display_name, timezone, target_calories, target_protein, target_carbs, target_fat, share_meals)
  values
    ('00000000-0000-0000-0000-00000000000a', 'Alex Demo',    'Europe/Berlin', 2200, 160, 230, 70, true),
    ('00000000-0000-0000-0000-00000000000b', 'Jonas Klein',  'Europe/Berlin', 2800, 180, 320, 85, true),
    ('00000000-0000-0000-0000-00000000000c', 'Lena Fischer', 'Europe/Berlin', 1900, 120, 210, 60, true),
    ('00000000-0000-0000-0000-00000000000d', 'Mia Wagner',   'Europe/Berlin', 2000, 130, 220, 65, false),
    ('00000000-0000-0000-0000-00000000000e', 'Tom Becker',   'Europe/Berlin', 2500, 150, 280, 80, true),
    ('00000000-0000-0000-0000-00000000000f', 'Sara Yilmaz',  'Europe/Berlin', 1800, 110, 200, 55, true);

  insert into friendships (requester_id, addressee_id, status, accepted_at) values
    ('00000000-0000-0000-0000-00000000000a', '00000000-0000-0000-0000-00000000000b', 'accepted', now()),
    ('00000000-0000-0000-0000-00000000000c', '00000000-0000-0000-0000-00000000000a', 'accepted', now()),
    ('00000000-0000-0000-0000-00000000000a', '00000000-0000-0000-0000-00000000000d', 'accepted', now()),
    ('00000000-0000-0000-0000-00000000000e', '00000000-0000-0000-0000-00000000000a', 'pending', null),
    ('00000000-0000-0000-0000-00000000000a', '00000000-0000-0000-0000-00000000000f', 'pending', null);

  -- ---------------------------------------------------------------------------
  -- Alex: 30 days of breakfast, lunch, dinner and a snack every third day.
  -- Days 9 and 17 ago are skipped, so the streak is 9 (today plus 8 days).
  -- ---------------------------------------------------------------------------
  create temp table dishes (label text, n int, title text, items jsonb);
  insert into dishes values
    ('breakfast', 0, 'Overnight oats with banana', '[["Rolled oats","80 g",300,11,54,6],["Milk","200 ml",130,7,10,7],["Banana","1 medium",105,1,27,0.4]]'),
    ('breakfast', 1, 'Scrambled eggs on sourdough', '[["Eggs, scrambled","3 eggs",215,19,1,15],["Sourdough toast","2 slices",230,8,44,2],["Butter","10 g",72,0,0,8]]'),
    ('breakfast', 2, 'Greek yogurt with granola and berries', '[["Greek yogurt","250 g",240,25,10,10],["Granola","50 g",225,5,32,9],["Blueberries","100 g",57,1,14,0.3]]'),
    ('breakfast', 3, 'Protein shake and a banana', '[["Whey protein","1 scoop",120,24,3,1.5],["Oat milk","300 ml",135,3,20,4.5],["Banana","1 medium",105,1,27,0.4]]'),
    ('lunch', 0, 'Chicken rice bowl', '[["Chicken breast","180 g",300,56,0,6.5],["White rice, cooked","200 g",260,5,57,0.6],["Broccoli","100 g",35,2.8,7,0.4],["Teriyaki sauce","30 ml",45,1,9,0]]'),
    ('lunch', 1, 'Döner kebab', '[["Pita bread","1 large",275,9,55,1.5],["Döner meat","150 g",380,27,4,28],["Salad and garlic sauce","1 portion",110,2,8,8]]'),
    ('lunch', 2, 'Spaghetti bolognese', '[["Spaghetti","120 g dry",430,15,86,2],["Beef bolognese sauce","200 g",280,20,12,17],["Parmesan","15 g",60,5,0,4]]'),
    ('lunch', 3, 'Tuna salad wrap', '[["Flour tortilla","1 large",210,6,35,5],["Tuna","120 g",130,29,0,1],["Salad and yogurt dressing","1 portion",90,4,8,4.5]]'),
    ('dinner', 0, 'Salmon with potatoes and green beans', '[["Salmon fillet","180 g",370,36,0,24],["Boiled potatoes","250 g",190,5,43,0.3],["Green beans","150 g",45,2.7,10,0.3]]'),
    ('dinner', 1, 'Beef burrito bowl', '[["Ground beef","150 g",330,30,0,23],["Rice, cooked","150 g",195,4,43,0.4],["Black beans","100 g",130,9,23,0.5],["Salsa and cheese","1 portion",140,6,4,11]]'),
    ('dinner', 2, 'Pizza margherita', '[["Pizza margherita","1 pizza (30 cm)",850,34,105,30]]'),
    ('dinner', 3, 'Chicken curry with naan', '[["Chicken curry","350 g",480,38,18,28],["Naan bread","1 piece",260,9,45,5]]'),
    ('snack', 0, 'Protein bar', '[["Protein bar","1 bar (60 g)",210,20,22,7]]'),
    ('snack', 1, 'Apple and peanut butter', '[["Apple","1 medium",95,0.5,25,0.3],["Peanut butter","30 g",190,8,6,16]]'),
    ('snack', 2, 'Cappuccino and croissant', '[["Cappuccino","1 cup",110,6,9,6],["Butter croissant","1 piece",230,5,26,12]]');

  perform pg_temp.meal('00000000-0000-0000-0000-00000000000a',
                      ((now() at time zone 'Europe/Berlin')::date - ago + make_interval(hours => s.hour)) at time zone 'Europe/Berlin',
                      s.label, d.title, case when (ago + s.slot) % 3 = 0 then 'photo' else 'text' end, d.items)
  from generate_series(1, 29) ago
  cross join (values (0, 'breakfast', 8), (1, 'lunch', 13), (2, 'dinner', 19), (3, 'snack', 16)) s(slot, label, hour)
  join dishes d on d.label = s.label
    and d.n = (ago * 5 + s.slot * 3) % (select count(*) from dishes x where x.label = s.label)
  where ago not in (9, 17) and (s.slot < 3 or ago % 3 = 0);

  -- Today so far: breakfast and lunch
  perform pg_temp.meal('00000000-0000-0000-0000-00000000000a', now() - interval '4 hours', 'breakfast',
                      title, 'text', items) from dishes where label = 'breakfast' and n = 2;
  perform pg_temp.meal('00000000-0000-0000-0000-00000000000a', now() - interval '1 hour', 'lunch',
                      title, 'photo', items) from dishes where label = 'lunch' and n = 0;

  insert into custom_foods (user_id, name, serving_label, calories, protein, carbs, fat) values
    ('00000000-0000-0000-0000-00000000000a', 'My usual oats', '1 bowl', 535, 19, 91, 13.4),
    ('00000000-0000-0000-0000-00000000000a', 'Skyr', '1 cup (150 g)', 95, 16.5, 6, 0.3),
    ('00000000-0000-0000-0000-00000000000a', 'Mensa schnitzel with fries', '1 plate', 980, 42, 88, 50);

  -- ---------------------------------------------------------------------------
  -- Friends' meals: the feed shows the last 24 hours, a friend's page shows today
  -- ---------------------------------------------------------------------------
  create temp table photo_meals (key text, meal_id uuid);

  insert into photo_meals select 'pancakes', pg_temp.meal('00000000-0000-0000-0000-00000000000b', now() - interval '5 hours', 'breakfast',
    'Banana pancakes with maple syrup', 'photo',
    '[["Pancakes","5 small",450,12,62,16],["Banana","1/2",52,0.5,13.5,0.2],["Maple syrup","2 tbsp",105,0,27,0]]');
  insert into photo_meals select 'bowl', pg_temp.meal('00000000-0000-0000-0000-00000000000b', now() - interval '2 hours', 'lunch',
    'Chicken power bowl', 'photo',
    '[["Grilled chicken","150 g",250,46,0,6],["Boiled eggs","2 quail eggs",30,2.5,0,2],["Sweet corn","80 g",70,2.5,15,1],["Edamame","60 g",75,7,5,3],["Cherry tomatoes, cucumber, red cabbage","1 portion",50,2,10,0.5],["Lettuce","1 handful",5,0.5,1,0]]');
  insert into photo_meals select 'pizza', pg_temp.meal('00000000-0000-0000-0000-00000000000b', now() - interval '20 hours', 'dinner',
    'BBQ chicken pizza', 'photo',
    '[["Pizza base","1 thin crust (30 cm)",520,16,96,8],["BBQ chicken","120 g",230,28,10,8],["Mozzarella","100 g",280,22,2,20],["Pineapple and red onion","1 portion",50,0.5,12,0.1]]');

  perform pg_temp.meal('00000000-0000-0000-0000-00000000000c', now() - interval '6 hours', 'breakfast', title, 'text', items)
  from dishes where label = 'breakfast' and n = 0;
  insert into photo_meals select 'veggie', pg_temp.meal('00000000-0000-0000-0000-00000000000c', now() - interval '3 hours', 'lunch',
    'Rainbow veggie bowl with chickpeas', 'photo',
    '[["Avocado","1/2",160,2,9,15],["Roasted sweet potato","150 g",135,2.4,31,0.2],["Chickpeas","80 g",130,7,22,2],["Cherry tomatoes","100 g",18,0.9,4,0.2],["Lettuce, red cabbage, pepper, radish","1 portion",45,2,9,0.4],["Tahini dressing","1 tbsp",90,2.6,3,8]]');
  insert into photo_meals select 'salad', pg_temp.meal('00000000-0000-0000-0000-00000000000c', now() - interval '18 hours', 'dinner',
    'Salad with feta, olives and walnuts', 'photo',
    '[["Mixed salad and carrot","1 large bowl",60,3,10,0.5],["Feta","50 g",130,7,2,10.5],["Olives","30 g",45,0.3,1,4.5],["Walnuts","20 g",130,3,3,13],["Orange juice","250 ml",112,1.7,26,0.5]]');
  -- Logged by hand, so there's nothing to expand
  insert into meals (user_id, log_date, logged_at, meal_label, description, source, calories, protein, carbs, fat)
  values ('00000000-0000-0000-0000-00000000000c', ((now() - interval '1 hour') at time zone 'Europe/Berlin')::date,
          now() - interval '1 hour', 'snack', 'Protein bar', 'manual', 200, 20, 20, 7);

  -- Mia isn't sharing, so none of this shows up anywhere
  perform pg_temp.meal('00000000-0000-0000-0000-00000000000d', now() - interval '3 hours', 'lunch', title, 'text', items)
  from dishes where label = 'lunch' and n = 1;

